__NUXT_JSONP__("/posts/building-a-restaurant-page-using-nuxt-with-storyblok", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M){return {data:[{post:{slug:u,description:r,title:"Building a restaurant page using Nuxt with Storyblok",type:i,imgCover:u,tags:[s,v,"headless CMS",t,i],createdAt:"2020-10-07T00:00:00.000Z",toc:[{id:w,depth:k,text:x},{id:y,depth:k,text:z},{id:A,depth:k,text:B},{id:C,depth:k,text:D},{id:E,depth:k,text:F},{id:G,depth:k,text:H}],body:{type:I,children:[{type:b,tag:j,props:{},children:[{type:a,value:r}]},{type:a,value:d},{type:a,value:d},{type:b,tag:l,props:{id:w},children:[{type:b,tag:c,props:{href:"#genesis",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:x}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"I have a brother who owns of small "},{type:b,tag:c,props:{href:J,rel:[e,f,g],target:h},children:[{type:a,value:"pizzeria"}]},{type:a,value:" in Libourne, west of France. I did built a small webpage containing contact details back in time, but he had the need to publicly expose its restaurant’s menu and be able to update himself on a regular basis. It was a perfect opportunity to go with a static site powered by a headless CMS following the "},{type:b,tag:c,props:{href:"https:\u002F\u002Fjamstack.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Jamstack"}]},{type:a,value:" approach, as the site would only be updated a few times a month."}]},{type:a,value:d},{type:b,tag:l,props:{id:y},children:[{type:b,tag:c,props:{href:"#the-choice-of-storyblok",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:z}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"Previously, I only experimented "},{type:b,tag:c,props:{href:"https:\u002F\u002Fprismic.io\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Prismic"}]},{type:a,value:" as headless CMS, and even though I was quite happy, I felt like the UI lacked a bit of intuitiveness, especially on the editor side. I heard about "},{type:b,tag:c,props:{href:"https:\u002F\u002Fwww.storyblok.com\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Storyblok"}]},{type:a,value:" as a headless solution that is frequently coupled with Nuxt. Indeed, there is multiples tutorials and Nuxt boilerplates into their documentation. It seems Storyblok people have made Nuxt their beloved front-end solution. I was convinced to try it out after I’ve seen a few tutorial showing a neat and appealing admin UI. The free tiers is also quite generous and encompasses all the features I would need (content documents can be organized in a folder-like structure, very simple forms, web hooks ..)"}]},{type:a,value:d},{type:b,tag:l,props:{id:A},children:[{type:b,tag:c,props:{href:"#the-highlights-of-storyblok",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:B}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"The feature I found the most interesting is the one Storyblok showcases : "},{type:b,tag:c,props:{href:"https:\u002F\u002Fwww.storyblok.com\u002Fdocs\u002Fthe-editor",rel:[e,f,g],target:h},children:[{type:a,value:"the visual editor"}]},{type:a,value:" that offers us to directly click on page elements that display the right edition form on the side. I think it speed up the editor’s work and help him to quickly preview all the changes made before publishing. Prismic has a "},{type:b,tag:c,props:{href:"https:\u002F\u002Fuser-guides.prismic.io\u002Fen\u002Farticles\u002F781294-how-to-set-up-a-preview",rel:[e,f,g],target:h},children:[{type:a,value:"preview feature"}]},{type:a,value:" but we should open the page in an external window and should go back and forth."}]},{type:a,value:d},{type:b,tag:l,props:{id:C},children:[{type:b,tag:c,props:{href:"#the-storybloks-nuxt-boilerplate",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:D}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"From the developer side, the "},{type:b,tag:c,props:{href:K,rel:[e,f,g],target:h},children:[{type:a,value:"Nuxt Storyblok SDK"}]},{type:a,value:" is pretty straightforward to setup and querying the API is very simple. The team responsible for the "},{type:b,tag:c,props:{href:K,rel:[e,f,g],target:h},children:[{type:a,value:"Nuxt boilerplate"}]},{type:a,value:" has made an interesting architecture choice : every page\u002Fcomponent is made using a dynamic component calling the one using the reference name retrieved from the API, and pass it all the data in a \"blok\" prop. All the components are referenced in a single components.js file called within plugin property within nuxt.config.js. This way, it’s almost always the same code we can reuse across pages and components."}]},{type:a,value:d},{type:b,tag:l,props:{id:E},children:[{type:b,tag:c,props:{href:"#problem-encountered",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:F}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"The Storyblok experience has been fluid on the whole process, though, I struggled a bit on the deployment phase. I couldn’t take advantage on the dynamic visual editor onto the deployed static site (on "},{type:b,tag:c,props:{href:"http:\u002F\u002Fnetlify.com\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Netlify"}]},{type:a,value:"), pretty annoying.  It may be fixed in a near future but the only workaround I found is to deploy another parallel app, either SPA or SSR, and call this one on the visual editor."}]},{type:a,value:d},{type:b,tag:l,props:{id:G},children:[{type:b,tag:c,props:{href:"#wrapping-up",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:H}]},{type:a,value:d},{type:b,tag:j,props:{},children:[{type:a,value:"This stack is simple. Storyblok is neat and offers a great editor experience. I’m eager to improve my Storyblok knowledge across upcoming projects regarding this positive first impression. Here is the restaurant site by the way, called "},{type:b,tag:c,props:{href:J,rel:[e,f,g],target:h},children:[{type:a,value:"Marcellino"}]},{type:a,value:"."}]}]},excerpt:{type:I,children:[{type:b,tag:j,props:{},children:[{type:a,value:r}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fbuilding-a-restaurant-page-using-nuxt-with-storyblok",extension:".md",updatedAt:"2025-10-10T15:29:17.520Z"},relatedPosts:[{title:"Transitioning from graphic design to front-end development",type:i,imgCover:"transitioning-graphic-design-front-end-development",tags:[L,i],createdAt:"2019-01-07T00:00:00.000Z",path:"\u002Fposts\u002Ftransitioning-graphic-design-front-end-development"},{title:"Testing a headless architecture with Nuxt + Prismic",type:i,imgCover:"testing-a-headless-architecture-with-nuxt-prismic",tags:["netlify","prismic",s,t,i],createdAt:"2020-04-02T00:00:00.000Z",path:"\u002Fposts\u002Ftesting-a-headless-architecture-with-nuxt-prismic"},{title:"lansolo99 dev page",type:M,imgCover:"lansolo99-dev-page",tags:["gridsome",t,M],createdAt:"2020-04-12T00:00:00.000Z",path:"\u002Fposts\u002Flansolo99-dev-page"},{title:"Vue.js + Vuex form binding",type:i,imgCover:"vue-js-vuex-form-binding",tags:[s,v,"vuex","form",L,i],createdAt:"2020-12-15T00:00:00.000Z",path:"\u002Fposts\u002Fvue-js-vuex-form-binding"}]}],fetch:[{counter:15},{counter:13},{counter:1},{counter:32},{counter:72}],mutations:[]}}("text","element","a","\n","nofollow","noopener","noreferrer","_blank","article","p",2,"h2","true",-1,"span","icon","icon-link","This post is about my first experience using Storyblok headless CMS coupled with Nuxt.","nuxt","devs","building-a-restaurant-page-using-nuxt-with-storyblok","vue","genesis","Genesis","the-choice-of-storyblok","The choice of Storyblok","the-highlights-of-storyblok","The highlights of Storyblok","the-storybloks-nuxt-boilerplate","The Storyblok’s Nuxt boilerplate","problem-encountered","Problem encountered","wrapping-up","Wrapping up","root","http:\u002F\u002Fmarcellino.net","https:\u002F\u002Fgithub.com\u002Fstoryblok\u002Fstoryblok-nuxt","miscs","design")));